raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R23-01",
   "status": "OK",
   "label": "1인 1계좌 제한",
   "source": {
    "quote": "▪ 이 통장은「KB Young Youth 청소년통장」을 포함하여 1인 1계좌만 가입 가능하며, 공동명의로 가입할 수 없습니다."
   },
   "condition": {
    "not": {
     "in": [
      {
       "var": "customer.holder_type"
      },
      [
       "INDIVIDUAL",
       "SOLE_PROPRIETOR",
       "REGISTERED_ASSOCIATION"
      ]
     ]
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R23-02",
   "status": "OK",
   "label": "저금통 설정 한도",
   "source": {
    "quote": "▪ 부가서비스 저금통 설정은 최대 100만원까지 가능하며, 저금통 설정된 금액을 출금(이체)하고자 하는 경우, 필요금액만큼 저금통 금액 차감 후 처리하여야 합니다."
   },
   "effect": {
    "type": "REQUIRE",
    "value": 1000000
   }
  },
  {
   "rule_id": "R-KBYY-S2-R23-03",
   "status": "OK",
   "label": "전환계좌 금리 적용 시기",
   "source": {
    "quote": "▪ 전환계좌의 경우 전환 후 최초 결산기(지난 결산일부터 결산일 전일까지)에 대해서는 전환 전(前) 예금의 금리를 적용하고, 다음 결산기부터 전환된 예금의 금리를 적용합니다."
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "전환 전 금리"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R23-04",
   "status": "OK",
   "label": "전환 시 재전환 제한",
   "source": {
    "quote": "▪ 이 통장에서 다른 통장으로의 전환 시 다음 결산일(매년 2월, 5월, 8월, 11월의 둘째 금요일)까지는 이 통장으로 재전환이 불가합니다."
   },
   "condition": {
    "not": {
     "in": [
      {
       "var": "contract.switch_date"
      },
      [
       {
        "month_of": [2, 5, 8, 11],
        "day": {
         "weekday": "FRI",
         "nth": 2
        }
       }
      ]
     ]
    }
   },
   "effect": {
    "type": "RESTRICT",
    "target": "SWITCH_IN"
   }
  }
 ]
}

